import { getProducts } from './data'

export type CategoryData = {
  heading: string
  products: string[]
}

const categoryHeading: Record<string, string> = {
  featured: 'Featured products',
  sale: 'Products on sale',
}

const cache = new Map<string, CategoryData>()

export async function prefetchCategory(slug: string) {
  if (cache.has(slug)) return

  const products = await getProducts(slug)
  const heading = categoryHeading[slug] ?? 'Products'

  cache.set(slug, { heading, products })
}

export function readCategory(slug: string): CategoryData | undefined {
  return cache.get(slug)
}

'use client'

import Link from 'next/link'
import { useEffect } from 'react'
import { prefetchCategory } from '@/lib/cache'

const categories = [
  { slug: 'featured', label: 'Featured products' },
  { slug: 'sale', label: 'Products on sale' },
]

export default function Home() {
  useEffect(() => {
    Promise.all(categories.map((category) => prefetchCategory(category.slug)))
  }, [])

  return (
    <main>
      <h1>Shop by category</h1>
      <ul>
        {categories.map((category) => (
          <li key={category.slug}>
            <Link href={`/catalog?category=${category.slug}`}>
              {category.label}
            </Link>
          </li>
        ))}
      </ul>
    </main>
  )
}

'use client'

import { useSearchParams } from 'next/navigation'
import { useEffect, useState } from 'react'
import { prefetchCategory, readCategory, type CategoryData } from '@/lib/cache'

export default function CatalogPage() {
  const searchParams = useSearchParams()
  const category = searchParams.get('category') ?? 'featured'
  const [data, setData] = useState<CategoryData | undefined>(() =>
    readCategory(category)
  )

  useEffect(() => {
    if (data) return

    prefetchCategory(category).then(() => {
      setData(readCategory(category))
    })
  }, [category, data])

  if (!data) {
    return null
  }

  return (
    <main>
      <h1>Catalog</h1>
      <section>
        <h2>{data.heading}</h2>
        <ul>
          {data.products.map((product) => (
            <li key={product}>{product}</li>
          ))}
        </ul>
      </section>
    </main>
  )
}

